-- User data as 0.15 left it, on the fixture layout's tags: schema from tag v0.15.0, at least a row in each table that names an
-- album, an artist or a track, each under the id 0.15 gave it: `al-<hash>`, `ar-<hash>`, `tr-<n>`.
CREATE TABLE annotation ( user TEXT NOT NULL, item TEXT NOT NULL, kind TEXT NOT NULL, pid TEXT, play_count INTEGER NOT NULL DEFAULT 0, play_date INTEGER, rating INTEGER NOT NULL DEFAULT 0, starred INTEGER NOT NULL DEFAULT 0, starred_at INTEGER, own_count INTEGER NOT NULL DEFAULT 0, own_date INTEGER, PRIMARY KEY (user, item, kind)) WITHOUT ROWID;
CREATE TABLE play_queue ( user TEXT PRIMARY KEY, songs TEXT NOT NULL, current TEXT, position_ms INTEGER NOT NULL DEFAULT 0, changed INTEGER NOT NULL, changed_by TEXT);
CREATE TABLE app_queue ( user TEXT NOT NULL, client TEXT NOT NULL, songs TEXT NOT NULL, current INTEGER, position_ms INTEGER NOT NULL DEFAULT 0, changed INTEGER NOT NULL, PRIMARY KEY (user, client)) WITHOUT ROWID;
CREATE TABLE added (album TEXT PRIMARY KEY, at INTEGER NOT NULL, origin TEXT NOT NULL);
CREATE TABLE playlist_seen (name TEXT PRIMARY KEY, print TEXT NOT NULL, created INTEGER NOT NULL, changed INTEGER NOT NULL);
CREATE TABLE album_review (album TEXT PRIMARY KEY, base TEXT NOT NULL, state TEXT NOT NULL, at INTEGER NOT NULL, undo TEXT, name TEXT NOT NULL, album_artist TEXT NOT NULL);
CREATE TABLE imported ( account TEXT NOT NULL, source TEXT NOT NULL, server_user TEXT NOT NULL, kind TEXT NOT NULL, item TEXT NOT NULL, server_item TEXT, pid TEXT, plays INTEGER NOT NULL DEFAULT 0, played INTEGER, starred INTEGER NOT NULL DEFAULT 0, rating INTEGER NOT NULL DEFAULT 0, at INTEGER NOT NULL, PRIMARY KEY (account, source, server_user, kind, item)) WITHOUT ROWID;
CREATE TABLE import_choices (source TEXT PRIMARY KEY, choice TEXT NOT NULL);
CREATE TABLE bookmark ( user TEXT NOT NULL, item TEXT NOT NULL, pid TEXT, position_ms INTEGER NOT NULL, comment TEXT NOT NULL DEFAULT '', created INTEGER NOT NULL, changed INTEGER NOT NULL, changed_by TEXT, PRIMARY KEY (user, item)) WITHOUT ROWID;
CREATE TABLE playlist_alias (old TEXT PRIMARY KEY, name TEXT NOT NULL, at INTEGER NOT NULL);
CREATE TABLE playlist_entry ( playlist TEXT NOT NULL, entry TEXT NOT NULL, n INTEGER NOT NULL, added INTEGER NOT NULL, PRIMARY KEY (playlist, entry, n)) WITHOUT ROWID;
CREATE TABLE visual_snapshot ( user TEXT NOT NULL, id TEXT NOT NULL, name TEXT NOT NULL, settings TEXT NOT NULL, created INTEGER NOT NULL, picture TEXT, PRIMARY KEY (user, id));
CREATE TABLE visual_rating ( user TEXT NOT NULL, at INTEGER NOT NULL, a TEXT NOT NULL, b TEXT NOT NULL, choice TEXT NOT NULL, track TEXT, context TEXT);
CREATE TABLE visual_thumb (user TEXT NOT NULL, at INTEGER NOT NULL, thumb TEXT NOT NULL, body TEXT NOT NULL);
CREATE TABLE visual_limits ( user TEXT PRIMARY KEY, version INTEGER NOT NULL, limits TEXT NOT NULL, at INTEGER NOT NULL);
CREATE TABLE playlist_shared (playlist TEXT PRIMARY KEY, at INTEGER NOT NULL);
CREATE TABLE user_settings (user TEXT PRIMARY KEY, version INTEGER NOT NULL, settings TEXT NOT NULL, at INTEGER NOT NULL);
CREATE TABLE plays ( user TEXT NOT NULL, song TEXT NOT NULL, pid TEXT, at INTEGER NOT NULL, heard_secs REAL, length_secs REAL, ended TEXT NOT NULL, counted INTEGER NOT NULL, player TEXT, output TEXT, context TEXT, event TEXT, followed INTEGER NOT NULL DEFAULT 0);
CREATE TABLE scrobble_target ( user TEXT NOT NULL, target TEXT NOT NULL, name TEXT NOT NULL, secret TEXT NOT NULL, broken TEXT, at INTEGER NOT NULL, off INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (user, target)) WITHOUT ROWID;
CREATE TABLE scrobble_queue ( id INTEGER PRIMARY KEY, user TEXT NOT NULL, target TEXT NOT NULL, song TEXT NOT NULL, at INTEGER NOT NULL, tries INTEGER NOT NULL DEFAULT 0, next INTEGER NOT NULL DEFAULT 0, why TEXT, named TEXT);
CREATE TABLE discover_found (user TEXT PRIMARY KEY, at INTEGER NOT NULL, found TEXT NOT NULL) WITHOUT ROWID;
CREATE TABLE discover_around (user TEXT PRIMARY KEY, state TEXT NOT NULL) WITHOUT ROWID;
CREATE TABLE discover_answer ( user TEXT NOT NULL, album TEXT NOT NULL, artist TEXT NOT NULL, answer TEXT NOT NULL, at INTEGER NOT NULL, name TEXT, artist_name TEXT, year INTEGER, cover TEXT, PRIMARY KEY (user, album)) WITHOUT ROWID;
CREATE TABLE request ( id INTEGER PRIMARY KEY AUTOINCREMENT, user TEXT NOT NULL, album_key TEXT NOT NULL, artist_key TEXT NOT NULL, release_group TEXT, album TEXT NOT NULL, artist TEXT NOT NULL, year INTEGER, cover TEXT, at INTEGER NOT NULL, status TEXT NOT NULL, reason TEXT, decided_by TEXT, decided_at INTEGER, fetched TEXT);
CREATE TABLE discography (artist TEXT PRIMARY KEY, at INTEGER NOT NULL, groups TEXT NOT NULL) WITHOUT ROWID;
CREATE TABLE related_artists (artist TEXT PRIMARY KEY, at INTEGER NOT NULL, found TEXT NOT NULL) WITHOUT ROWID;
CREATE TABLE bandcamp_found (album TEXT PRIMARY KEY, at INTEGER NOT NULL, page TEXT) WITHOUT ROWID;
CREATE TABLE original_years (release TEXT PRIMARY KEY, year INTEGER, at INTEGER NOT NULL) WITHOUT ROWID;
CREATE TABLE release_types (key TEXT PRIMARY KEY, primary_type TEXT, secondary TEXT NOT NULL, at INTEGER NOT NULL, rule INTEGER NOT NULL DEFAULT 0) WITHOUT ROWID;
CREATE TABLE renumber_matched (album TEXT PRIMARY KEY, at INTEGER NOT NULL) WITHOUT ROWID;
CREATE TABLE rg_covers (rg TEXT PRIMARY KEY, url TEXT, at INTEGER NOT NULL) WITHOUT ROWID;
CREATE TABLE discogs_genres (album TEXT PRIMARY KEY, genres TEXT NOT NULL, at INTEGER NOT NULL) WITHOUT ROWID;
CREATE TABLE album_tags (album TEXT NOT NULL, tag TEXT NOT NULL, at INTEGER NOT NULL, PRIMARY KEY (album, tag)) WITHOUT ROWID;
CREATE TABLE words ( subject TEXT NOT NULL, source TEXT NOT NULL, word TEXT NOT NULL, kind TEXT NOT NULL, weight REAL NOT NULL, at INTEGER NOT NULL, PRIMARY KEY (subject, source, word)) WITHOUT ROWID;
CREATE TABLE words_asked (subject TEXT NOT NULL, source TEXT NOT NULL, at INTEGER NOT NULL, ok INTEGER NOT NULL, PRIMARY KEY (subject, source)) WITHOUT ROWID;
CREATE TABLE album_matches (album TEXT PRIMARY KEY, at INTEGER NOT NULL, found TEXT) WITHOUT ROWID;
CREATE TABLE album_complete (album TEXT PRIMARY KEY, at INTEGER NOT NULL, found TEXT, discs INTEGER, rule INTEGER NOT NULL DEFAULT 0) WITHOUT ROWID;
CREATE TABLE discogs_facts (subject TEXT PRIMARY KEY, at INTEGER NOT NULL, facts TEXT) WITHOUT ROWID;
CREATE TABLE intake_heard (album TEXT PRIMARY KEY, at INTEGER NOT NULL, heard TEXT NOT NULL) WITHOUT ROWID;
CREATE TABLE record_references (album TEXT PRIMARY KEY, chosen TEXT NOT NULL) WITHOUT ROWID;
CREATE TABLE track_words (track TEXT NOT NULL, kind TEXT NOT NULL, words TEXT NOT NULL, at INTEGER NOT NULL, PRIMARY KEY (track, kind)) WITHOUT ROWID;
CREATE TABLE mb_releases (release TEXT PRIMARY KEY, found INTEGER NOT NULL, facts TEXT NOT NULL, at INTEGER NOT NULL) WITHOUT ROWID;
CREATE TABLE mb_works (work TEXT PRIMARY KEY, title TEXT NOT NULL, composers TEXT NOT NULL, at INTEGER NOT NULL) WITHOUT ROWID;
CREATE TABLE mb_work_parents (work TEXT PRIMARY KEY, parent TEXT NOT NULL, title TEXT NOT NULL, number INTEGER, at INTEGER NOT NULL) WITHOUT ROWID;
CREATE TABLE artist_person (artist TEXT PRIMARY KEY, person TEXT, name TEXT, discogs INTEGER, at INTEGER NOT NULL DEFAULT 0) WITHOUT ROWID;
CREATE TABLE discogs_names (discogs INTEGER PRIMARY KEY, realname TEXT, aliases TEXT NOT NULL, at INTEGER NOT NULL);
CREATE TABLE discogs_link_genres (link TEXT PRIMARY KEY, genres TEXT NOT NULL, at INTEGER NOT NULL) WITHOUT ROWID;
CREATE TABLE classical_marks (album TEXT PRIMARY KEY, mark TEXT NOT NULL, at INTEGER NOT NULL) WITHOUT ROWID;
CREATE TABLE composer_keys (key TEXT PRIMARY KEY, name TEXT NOT NULL, alias_of TEXT, at INTEGER NOT NULL) WITHOUT ROWID;
CREATE TABLE record_overrides (album TEXT NOT NULL, field TEXT NOT NULL, value TEXT NOT NULL, at INTEGER NOT NULL, PRIMARY KEY (album, field)) WITHOUT ROWID;
CREATE TABLE play_seen (id TEXT PRIMARY KEY, at INTEGER NOT NULL) WITHOUT ROWID;
CREATE TABLE kept_answer ( user TEXT NOT NULL, key TEXT NOT NULL, asked TEXT NOT NULL, status INTEGER NOT NULL, kind TEXT, body BLOB NOT NULL, at INTEGER NOT NULL, PRIMARY KEY (user, key)) WITHOUT ROWID;
CREATE TABLE change_at ( account TEXT NOT NULL, kind TEXT NOT NULL, item TEXT NOT NULL, at INTEGER NOT NULL, PRIMARY KEY (account, kind, item)) WITHOUT ROWID;
CREATE TABLE change_log ( rev INTEGER PRIMARY KEY AUTOINCREMENT, account TEXT NOT NULL, kind TEXT NOT NULL, item TEXT NOT NULL, op TEXT NOT NULL, at INTEGER NOT NULL, shared INTEGER NOT NULL DEFAULT 0, seen_by TEXT NOT NULL DEFAULT '');
CREATE TABLE change_log_floor (one INTEGER PRIMARY KEY CHECK (one = 1), rev INTEGER NOT NULL);
CREATE TABLE playlist_entry_id ( playlist TEXT NOT NULL, entry TEXT NOT NULL, n INTEGER, line TEXT NOT NULL, placed INTEGER NOT NULL DEFAULT 0, gone INTEGER, after TEXT, PRIMARY KEY (playlist, entry)) WITHOUT ROWID;
CREATE TABLE playlist_op (account TEXT NOT NULL, op_id TEXT NOT NULL, at INTEGER NOT NULL, why TEXT, PRIMARY KEY (account, op_id)) WITHOUT ROWID;
CREATE TABLE scrobble_seen ( user TEXT NOT NULL, id TEXT NOT NULL, at INTEGER NOT NULL, PRIMARY KEY (user, id)) WITHOUT ROWID;
CREATE TABLE excluded_artist (user TEXT NOT NULL, key TEXT NOT NULL, name TEXT NOT NULL, at INTEGER NOT NULL, PRIMARY KEY (user, key)) WITHOUT ROWID;
CREATE INDEX annotation_starred ON annotation (user, kind, starred, starred_at);
CREATE INDEX annotation_played ON annotation (user, kind, play_date);
CREATE INDEX annotation_plays ON annotation (user, kind, play_count);
CREATE INDEX annotation_pid ON annotation (pid);
CREATE INDEX album_review_by_base ON album_review (base);
CREATE INDEX imported_pid ON imported (pid);
CREATE INDEX bookmark_pid ON bookmark (pid);
CREATE INDEX plays_by_user ON plays (user, at);
CREATE UNIQUE INDEX plays_by_event ON plays (event) WHERE event IS NOT NULL;
CREATE INDEX scrobble_queue_due ON scrobble_queue (next, at);
CREATE INDEX request_status ON request (status, at);
CREATE INDEX album_tags_by_tag ON album_tags (tag, album);
CREATE INDEX play_seen_at ON play_seen (at);
CREATE INDEX kept_answer_at ON kept_answer (at);
CREATE INDEX playlist_entry_id_gone ON playlist_entry_id (gone);
CREATE INDEX playlist_op_at ON playlist_op (at);
CREATE UNIQUE INDEX change_log_one ON change_log (account, kind, item, seen_by);
CREATE INDEX scrobble_seen_at ON scrobble_seen (at);
CREATE INDEX annotation_own_played ON annotation (user, kind, own_date);
-- The week before the log, as 0.15 wrote it from the last play of a track the merge takes.
-- Rows under an id no album has now. A Keep left its plays under the id the album had in Incoming: Two Rooms.
-- A copy kept in Music left, and the release waits in Incoming: Just Arrived, by what Music called it.
-- A library that changed place: Far Bank went by its first place until then, and by the second since, one row of each.
-- And back: Just Arrived's library took the first place again, so what came between went by the second.
-- The same on a release both Incoming libraries hold: one record, an id each, and the first is the second's from before.
-- A release on two records, Music's and Incoming's: this id was Incoming's until its library changed place.
-- What no list shows (CR13): gone a while, by its own id; in a trash, by its own and its base; parked, by what Music called it.
